  "rewrite_sql": "-- Set timeouts to fail fast instead of queueing behind long-running queries
SET lock_timeout = '2s';
SET statement_timeout = '10s';

-- EXPAND PHASE: Add new display_name column alongside full_name
-- This allows both old code (using full_name) and new code (using display_name)
-- to coexist during the deployment window

-- Add the new column (nullable to avoid rewrite)
ALTER TABLE users ADD COLUMN display_name text;

-- Backfill display_name from full_name
-- For very large tables (millions of rows), this should be batched in a separate process
UPDATE users SET display_name = full_name WHERE display_name IS NULL;

-- Create function to keep both columns in sync during transition
CREATE OR REPLACE FUNCTION sync_user_name_columns()
RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- On insert, ensure both have the same value
        NEW.display_name := COALESCE(NEW.display_name, NEW.full_name);
        NEW.full_name := NEW.display_name;
    ELSIF TG_OP = 'UPDATE' THEN
        -- On update, sync whichever column changed
        IF NEW.full_name IS DISTINCT FROM OLD.full_name THEN
            NEW.display_name := NEW.full_name;
        ELSIF NEW.display_name IS DISTINCT FROM OLD.display_name THEN
            NEW.full_name := NEW.display_name;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Add trigger to keep columns in sync
CREATE TRIGGER trg_sync_user_name_columns
    BEFORE INSERT OR UPDATE ON users
    FOR EACH ROW
    EXECUTE FUNCTION sync_user_name_columns();",
